-- Daxing'anling is a prefecture-level formal business root. Its seven
-- county-level children, boundary provenance and scope counts share one contract.
-- Canonical display geometry comes from fixed Overture division_area features;
-- simplification is limited to ~22 m for browser delivery and preserves topology.

DO $govern_regions$
DECLARE
  region_record record;
  operation_code varchar(16);
BEGIN
  FOR region_record IN
    SELECT * FROM (VALUES
      ('232700','大兴安岭地区',NULL,'PREFECTURE',40),
      ('232761','加格达奇区','232700','COUNTY',1),
      ('232762','松岭区','232700','COUNTY',2),
      ('232763','新林区','232700','COUNTY',3),
      ('232764','呼中区','232700','COUNTY',4),
      ('232701','漠河市','232700','COUNTY',5),
      ('232721','呼玛县','232700','COUNTY',6),
      ('232722','塔河县','232700','COUNTY',7)
    ) AS governed(code,name,parent_code,administrative_level,sort_order)
  LOOP
    operation_code:=CASE WHEN EXISTS(
      SELECT 1 FROM platform.region WHERE code=region_record.code
    ) THEN 'UPDATE' ELSE 'INSERT' END;

    PERFORM platform.govern_master_data_change(
      'REGION',region_record.code,operation_code,
      jsonb_build_object(
        'code',region_record.code,'name',region_record.name,
        'parent_code',region_record.parent_code,
        'administrative_level',region_record.administrative_level,
        'sort_order',region_record.sort_order),
      clock_timestamp(),
      'V137_DAXINGANLING_SOURCE_APPLICANT','V137_DAXINGANLING_INDEPENDENT_REVIEWER',
      '大兴安岭地区行政公署层级、业务代码与 Overture/OSM 边界交叉核验');
  END LOOP;
END;
$govern_regions$;

