INSERT INTO overview.administrative_boundary(
  region_code,geometry,source_name,source_url,source_revision,source_license,
  source_feature_id,source_effective_on,geometry_sha256,loaded_at)
SELECT region_code,geometry,source_name,source_url,source_revision,source_license,
       source_feature_id,source_effective_on,
       encode(sha256(ST_AsEWKB(geometry)),'hex'),now()
FROM source_boundary
ON CONFLICT(region_code) DO UPDATE SET
  geometry=EXCLUDED.geometry,
  source_name=EXCLUDED.source_name,
  source_url=EXCLUDED.source_url,
  source_revision=EXCLUDED.source_revision,
  source_license=EXCLUDED.source_license,
  source_feature_id=EXCLUDED.source_feature_id,
  source_effective_on=EXCLUDED.source_effective_on,
  geometry_sha256=EXCLUDED.geometry_sha256,
  loaded_at=EXCLUDED.loaded_at;

DO $validate_boundaries$
DECLARE
  invalid_count integer;
  outside_parent_count integer;
BEGIN
  WITH expected(code,xmin,xmax,ymin,ymax,min_area_km2,max_area_km2) AS (VALUES
      ('232700',121.18413680,127.02434430,50.11703760,53.56082540,81341.05,84661.09),
      ('232761',123.75831400,124.43576270,50.16380630,50.57159020,1345.04,1399.94),
      ('232701',121.18413680,124.27975140,52.25228970,53.56082540,18116.88,18856.34),
      ('232721',125.06543550,127.02434430,50.90235750,52.89670870,14281.08,14863.99),
      ('232722',123.31760970,125.81997930,52.15792650,53.34612460,13727.26,14287.56),
      ('232762',123.48919350,126.06969010,50.11703760,51.66043780,16514.64,17188.71),
      ('232763',123.69360090,125.45327320,51.27192690,52.33715620,8222.01,8557.60),
      ('232764',122.61834250,124.17331060,51.24609250,52.42008820,9134.14,9506.96)
  )
  SELECT count(*) INTO invalid_count
  FROM expected
  LEFT JOIN overview.administrative_boundary boundary ON boundary.region_code=expected.code
  WHERE boundary.geometry IS NULL
     OR boundary.source_feature_id IS NULL
     OR boundary.source_license<>'ODbL-1.0'
     OR NOT ST_IsValid(boundary.geometry)
     OR ST_IsEmpty(boundary.geometry)
     OR ST_XMin(Box3D(boundary.geometry)) NOT BETWEEN expected.xmin AND expected.xmin+0.00002
     OR ST_XMax(Box3D(boundary.geometry)) NOT BETWEEN expected.xmax-0.00002 AND expected.xmax
     OR ST_YMin(Box3D(boundary.geometry)) NOT BETWEEN expected.ymin AND expected.ymin+0.00002
     OR ST_YMax(Box3D(boundary.geometry)) NOT BETWEEN expected.ymax-0.00002 AND expected.ymax
     OR ST_Area(boundary.geometry::geography)/1000000
        NOT BETWEEN expected.min_area_km2 AND expected.max_area_km2;

  SELECT count(*) INTO outside_parent_count
  FROM overview.administrative_boundary child
  JOIN overview.administrative_boundary parent ON parent.region_code='232700'
  WHERE child.region_code IN ('232701','232721','232722','232761','232762','232763','232764')
    AND ST_Area(ST_Intersection(child.geometry,parent.geometry)::geography)
        / NULLIF(ST_Area(child.geometry::geography),0) < 0.999;

  IF invalid_count<>0 OR outside_parent_count<>0 THEN
    RAISE EXCEPTION 'Daxing-anling governed boundary gate failed: invalid %, outside parent %',
      invalid_count,outside_parent_count;
  END IF;
END;
$validate_boundaries$;

-- County display surfaces are the clickable, governed partition.  Rebuild
-- every affected prefecture display from those children so adding a new
-- neighbouring prefecture cannot leave sub-kilometre render slivers in an
-- existing prefecture after cross-border topology reconciliation.
CREATE OR REPLACE FUNCTION overview.refresh_administrative_boundary_render()
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM overview.refresh_administrative_boundary_render_source();
  PERFORM overview.clean_real_township_boundary_render();
  PERFORM overview.reconcile_real_named_primary_surfaces();
  PERFORM overview.close_root_prefecture_gaps('FORMAL_BUSINESS');

  -- Preserve the V55 contract: generate villages inside the actual final
  -- township geometry, including named township enclaves.
  PERFORM overview.repartition_display_children_watertight('VILLAGE');

  PERFORM overview.restore_administrative_boundary_render_provenance();

  WITH county_coverage AS (
    SELECT child.parent_code,
           ST_Multi(ST_UnaryUnion(ST_Collect(render.geometry)))
             ::geometry(MultiPolygon,4326) geometry
      FROM platform.region child
      JOIN overview.administrative_boundary_render render
        ON render.region_code=child.code
     WHERE child.administrative_level='COUNTY'
       AND child.parent_code IS NOT NULL
     GROUP BY child.parent_code
  )
  UPDATE overview.administrative_boundary_render parent
     SET geometry=coverage.geometry,
         geo_json=ST_AsGeoJSON(coverage.geometry,7),
         full_point_count=GREATEST(parent.full_point_count,ST_NPoints(coverage.geometry)),
         render_point_count=ST_NPoints(coverage.geometry),
         refreshed_at=now(),
         source_name=left(parent.source_name || '; exact child coverage',160)
    FROM county_coverage coverage
    JOIN platform.region parent_region
      ON parent_region.code=coverage.parent_code
     AND parent_region.administrative_level='PREFECTURE'
   WHERE parent.region_code=coverage.parent_code;

  TRUNCATE overview.administrative_map_context_region_render;
  PERFORM overview.assert_watertight_administrative_render();
  PERFORM overview.assert_clean_real_named_boundary_render();
END;
$$;

SELECT overview.refresh_administrative_boundary_render();
SELECT overview.refresh_monitoring_scope_boundary('FORMAL_BUSINESS');
SELECT overview.refresh_monitoring_scope_boundary_render('FORMAL_BUSINESS');

COMMENT ON COLUMN platform.monitoring_scope_region.business_root IS
  'Business navigation root, independent from the actual administrative parent. Scope totals are derived from included rows, never hard-coded.';
